import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("math",...args);
export const mathUtilsLessons=[
L("factorial","Count selections and arrangements",[2, 6, 7],"<p>A factorial counts arrangements of all items. <code>combinations(n, r)</code> ignores order; <code>permutations(n, r)</code> counts ordered selections. Use small nonnegative integers to avoid overflow.</p>","n = 5;\nr = 2;\nplayer:tell(\"FACTORIAL: \", toliteral($math_utils:factorial(n)));\nplayer:tell(\"COMBINATIONS: \", toliteral($math_utils:combinations(n, r)));\nplayer:tell(\"PERMUTATIONS: \", toliteral($math_utils:permutations(n, r)));",edit("r = 2;","r = 3;","Choose three items instead of two. The combination count stays 10, while the permutation count becomes 60.")),
L("divmod","Divide with a signed remainder",[5, 10, 11, 9],"<p>Unlike truncated division, <code>divmod()</code> chooses a remainder with the divisor\u2019s sign. <code>div()</code> and <code>mod()</code> expose the two parts. <code>parts()</code> instead separates a truncated quotient and scaled fractional digits.</p>","n = -7;\nd = 3;\nplayer:tell(\"DIVMOD quotient and remainder: \", toliteral($math_utils:divmod(n, d)));\nplayer:tell(\"DIV quotient: \", toliteral($math_utils:div(n, d)));\nplayer:tell(\"MOD remainder: \", toliteral($math_utils:mod(n, d)));\nplayer:tell(\"PARTS decimal digits: \", toliteral($math_utils:parts(7, 3, 2)));",edit("n = -7;","n = 7;","Use positive 7. The quotient and remainder become 2 and 1; the independent decimal decomposition stays the same.")),
L("gcd","Find common factors and cycles",[20, 21, 22, 16],"<p>Use <code>gcd()</code> to reduce a ratio and <code>lcm()</code> for repeating cycles. Relative primality means the greatest common divisor is one; it does not mean both numbers are prime. Avoid zero inputs to this core\u2019s GCD implementation.</p>","a = 12;\nb = 18;\nplayer:tell(\"GCD: \", toliteral($math_utils:gcd(a, b)));\nplayer:tell(\"LCM: \", toliteral($math_utils:lcm(a, b)));\nplayer:tell(\"RELATIVELY PRIME: \", toliteral($math_utils:are_rel_prime(a, b)));\nplayer:tell(\"IS PRIME 17: \", toliteral($math_utils:is_prime(17)));",edit("b = 18;","b = 25;","Change the second number to 25. GCD becomes 1, LCM becomes 300, and relative primality becomes true.")),
L("series","Build sequences and approximate a series",[3, 4, 12],"<p>The Fibonacci result includes term zero through the selected index. <code>geometric()</code> includes the constant term and the requested powers. Integer <code>exp()</code> returns integer and fractional parts; floating input uses the native exponential builtin.</p>","terms = 4;\nplayer:tell(\"FIBONACCI: \", toliteral($math_utils:fibonacci(terms)));\nplayer:tell(\"GEOMETRIC at one half: \", toliteral($math_utils:geometric(0.5, terms)));\nplayer:tell(\"EXP integer approximation: \", toliteral($math_utils:exp(1, terms)));\nplayer:tell(\"EXP float at zero: \", toliteral($math_utils:exp(0.0)));",edit("terms = 4;","terms = 5;","Add a term. Fibonacci gains 5 and the geometric approximation moves closer to 2; the integer exponential approximation also changes.")),
L("totals","Sum, average and report percentages",[35, 36, 37, 39],"<p>Use <code>sum_int()</code> (also <code>sum()</code>) for integer data and <code>sum_float()</code> for floating data, including a correctly typed empty total. Integer <code>mean()</code> truncates. <code>to_percent(part, whole)</code> produces a floating percentage.</p>","counts = {2, 4, 6};\nplayer:tell(\"SUM integers: \", toliteral($math_utils:sum_int(counts)));\nplayer:tell(\"MEAN integers: \", toliteral($math_utils:mean(counts)));\nplayer:tell(\"SUM floating: \", toliteral($math_utils:sum_float({1.5, 2.5})));\nplayer:tell(\"PERCENT complete: \", toliteral($math_utils:to_percent(3, 4)));",edit("counts = {2, 4, 6};","counts = {2, 4, 9};","Change the last count to 9. The integer total becomes 15 and its mean becomes 5.")),
L("rounding","Choose a rounding contract",[33, 34, 38],"<p>These helpers have different units: <code>round()</code> rounds an integer to a multiple, <code>precision()</code> rounds decimal places, and <code>rint()</code> returns a float rounded to an integer with ties away from zero.</p>","value = 2.5;\nplayer:tell(\"RINT positive: \", toliteral($math_utils:rint(value)));\nplayer:tell(\"RINT negative: \", toliteral($math_utils:rint(-value)));\nplayer:tell(\"PRECISION two places: \", toliteral($math_utils:precision(1.236, 2)));\nplayer:tell(\"ROUND to five: \", toliteral($math_utils:round(12, 5)));",edit("value = 2.5;","value = 2.4;","Use 2.4. The rounded floating values become 2.0 and -2.0.")),
L("bases","Convert number bases and inspect bits",[23, 17, 18, 19],"<p>Base conversion returns a string; digits above nine need letters. The binary-list helpers are historical 32-bit representations, so this example stays nonnegative. <code>NOT()</code> computes the signed complement as <code>-(1 + n)</code>.</p>","n = 10;\nbits = $math_utils:BLFromInt(n);\nplayer:tell(\"BASE hexadecimal: \", toliteral($math_utils:base_conversion(n, 10, 16)));\nplayer:tell(\"BITS least significant eight: \", toliteral(bits[25..32]));\nplayer:tell(\"BITS back to integer: \", toliteral($math_utils:IntFromBL(bits)));\nplayer:tell(\"NOT signed complement: \", toliteral($math_utils:NOT(n)));",edit("n = 10;","n = 15;","Use 15. Hexadecimal becomes F, the last four bits are ones, and the signed complement becomes -16.")),
L("angles","Convert angle units before trigonometry",[25, 26, 27, 31, 32],"<p>Floating arguments to <code>sin()</code>, <code>cos()</code> and <code>tan()</code> are radians. Integer arguments instead mean degrees and produce values scaled by 10,000. Convert explicitly; changing a literal\u2019s type changes its meaning.</p>","degrees = 0;\nradians = $math_utils:deg2rads(degrees);\nplayer:tell(\"RADIANS: \", toliteral(radians));\nplayer:tell(\"DEGREES round trip: \", toliteral($math_utils:rads2deg(radians)));\nplayer:tell(\"SIN radians: \", toliteral($math_utils:sin(radians)));\nplayer:tell(\"COS radians: \", toliteral($math_utils:cos(radians)));\nplayer:tell(\"TAN radians: \", toliteral($math_utils:tan(radians)));",edit("degrees = 0;","degrees = 0.0;","Use floating zero as the input. Explicit conversion preserves the same angle and results.")),
L("inverse-trig","Recover angles and measure an integer norm",[28, 29, 30, 24],"<p>Floating inverse trigonometric inputs return radians. The integer forms use historical scaled values and return degrees/minutes. <code>norm()</code> takes separate integer components and returns an integer approximation, unlike the Matrix Utils floating norm.</p>","x = 0.0;\nplayer:tell(\"ARCSIN radians: \", toliteral($math_utils:arcsin(x)));\nplayer:tell(\"ARCCOS radians: \", toliteral($math_utils:arccos(1.0)));\nplayer:tell(\"ARCTAN radians: \", toliteral($math_utils:arctan(x)));\nplayer:tell(\"NORM 3 4: \", toliteral($math_utils:norm(3, 4)));",edit("norm(3, 4)","norm(6, 8)","Double both norm components. The integer length doubles from 5 to 10.")),
L("integration","Approximate an area from three samples",[8],"<p>Simpson\u2019s rule combines the function at two endpoints and their midpoint. For the square function over zero to two, the samples are 0, 1 and 4. Integer input returns a scaled fractional pair unless the float-result option is enabled.</p>","samples = {0, 1, 4};\nplayer:tell(\"SIMPSON integer parts: \", toliteral($math_utils:simpson({0, 2}, samples)));\nplayer:tell(\"SIMPSON floating area: \", toliteral($math_utils:simpson({0, 2}, samples, 1)));",edit("samples = {0, 1, 4};","samples = {0, 2, 8};","Double every sample. The area doubles, illustrating the linearity of the weighted sum.")),
L("random","Read the bounds of random choices",[14, 15],"<p>Unlike the builtin\u2019s one-based convention, this utility\u2019s <code>random(n)</code> includes zero and the endpoint, including negative endpoints. <code>random_range(radius, center)</code> spans both sides of its center. The printed values vary.</p>","radius = 2;\nplayer:tell(\"RANDOM zero through two: \", toliteral($math_utils:random(radius)));\nplayer:tell(\"RANDOM minus two through zero: \", toliteral($math_utils:random(-radius)));\nplayer:tell(\"RANDOM around ten: \", toliteral($math_utils:random_range(radius, 10)));",edit("radius = 2;","radius = 1;","Reduce the radius to one. Choices stay in the displayed broad bounds but now use the narrower intervals 0..1, -1..0 and 9..11."),{"experimentOutputChoices":{"RANDOM zero through two: ":["0","1"],"RANDOM minus two through zero: ":["-1","0"],"RANDOM around ten: ":["9","10","11"]},"outputChoices": {"RANDOM zero through two: ": ["0", "1", "2"], "RANDOM minus two through zero: ": ["-2", "-1", "0"], "RANDOM around ten: ": ["8", "9", "10", "11", "12"]}}),
L("supply-budget","Combine a readable supply budget",[],"<p>Compute each stage before printing it. Sum the item counts, calculate the completion percentage, then round only the displayed percentage so the original calculation remains available.</p>","counts = {2, 3, 4};\nneeded = 12;\ntotal = $math_utils:sum(counts);\npercent = $math_utils:to_percent(total, needed);\nplayer:tell(\"ITEMS ready: \", toliteral(total));\nplayer:tell(\"PERCENT unrounded: \", toliteral(percent));\nplayer:tell(\"PERCENT displayed: \", toliteral($math_utils:precision(percent, 1)));",edit("needed = 12;","needed = 18;","Double the target relative to the available nine items. Completion becomes 50 percent.")),
];
export const mathExclusions={"0": "Legacy integer Taylor approximation; modern sin() and explicit angle conversion are taught instead.", "1": "Legacy integer Taylor approximation; modern cos() and explicit angle conversion are taught instead.", "13": "Legacy scaled-integer exponential; exp() covers the public modern calculation without fixed-point overflow assumptions."};
